diff --git a/core/src/com/agateau/pixelwheels/bonus/Missile.java b/core/src/com/agateau/pixelwheels/bonus/Missile.java
index e6a94a5..25893a8 100644
--- a/core/src/com/agateau/pixelwheels/bonus/Missile.java
+++ b/core/src/com/agateau/pixelwheels/bonus/Missile.java
@@ -29,6 +29,7 @@ import com.agateau.pixelwheels.gameobject.Explosable;
 import com.agateau.pixelwheels.gameobject.GameObjectAdapter;
 import com.agateau.pixelwheels.racer.Racer;
 import com.agateau.pixelwheels.racer.Vehicle;
+import com.agateau.pixelwheels.racer.VehicleRenderer;
 import com.agateau.pixelwheels.racescreen.Collidable;
 import com.agateau.pixelwheels.racescreen.CollisionCategories;
 import com.agateau.pixelwheels.sound.AudioManager;
@@ -137,7 +138,7 @@ public class Missile extends GameObjectAdapter
         Vehicle vehicle = shooter.getVehicle();
         object.mShooter = shooter;
         object.mBodyDef.position.set(vehicle.getX(), vehicle.getY());
-        object.mBodyDef.angle = AgcMathUtils.normalizeAnglePiRad(vehicle.getAngle());
+        object.mBodyDef.angle = AgcMathUtils.normalizeAnglePiRad(vehicle.getBody().getAngle());

         object.mBody = gameWorld.getBox2DWorld().createBody(object.mBodyDef);
         object.mBody.createFixture(object.mShape, WAITING_DENSITY);
@@ -258,14 +259,28 @@ public class Missile extends GameObjectAdapter

     @Override
     public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
+        if (mStatus == Status.WAITING) {
+            // Still attached to its vehicle: draw at the same level as the vehicle, with the same
+            // color, so that it gets hidden and tinted like the vehicle
+            VehicleRenderer vehicleRenderer = mShooter.getVehicleRenderer();
+            if (zLevel == vehicleRenderer.getZLevel()) {
+                // Draw the shadow at the vehicle level so that it is drawn *over* its vehicle
+                drawShadow(batch);
+                batch.setColor(vehicleRenderer.getBatchColor());
+                drawMissile(batch);
+                batch.setColor(Color.WHITE);
+            }
+            if (zLevel == ZLevel.FLYING) {
+                drawTarget(batch);
+            }
+            return;
+        }
         if (zLevel == ZLevel.FLYING) {
             // Draw the shadow at Z_FLYING so that the shadow is drawn *over* its vehicle
             drawShadow(batch);
             drawMissile(batch);
             drawTarget(batch);
-            if (mStatus != Status.WAITING) {
-                drawReactorFire(batch);
-            }
+            drawReactorFire(batch);
         }
     }

diff --git a/core/src/com/agateau/pixelwheels/racer/VehicleRenderer.java b/core/src/com/agateau/pixelwheels/racer/VehicleRenderer.java
index 7e8553c..f40d6e2 100644
